#!/usr/bin/env node
/**
 * Diagnostic probe (not part of the product): how many pages does the e-rara OAI
 * set `landkarten` have, and what do the map candidates look like per decade?
 *
 * Responses are written into the harvest's own `.cache/fetch/` (same key scheme),
 * so a later `npm run harvest` reuses them and the upstreams are queried once.
 */
import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { createHash } from 'node:crypto';
import { resolve } from 'node:path';

const UA = 'Kartenzeit/1.0 (Canton-Zurich design study; contact: project maintainers)';
const CACHE_DIR = resolve('/home/runner/work/maps-n-stuff/maps-n-stuff/.cache/fetch') + '/';
const hash = (url, as) => CACHE_DIR + createHash('sha1').update(url).digest('hex').slice(0, 20) + (as === 'json' ? '.json' : '.txt');

async function get(url) {
  const file = hash(url, 'text');
  try { return await readFile(file, 'utf8'); } catch {}
  const res = await fetch(url, { headers: { 'user-agent': UA, accept: '*/*' } });
  if (!res.ok) throw new Error(`${res.status} ${url}`);
  const body = await res.text();
  await mkdir(CACHE_DIR, { recursive: true });
  await writeFile(file, body);
  await new Promise((r) => setTimeout(r, 150));
  return body;
}

const decode = (s) => String(s || '').replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCodePoint(parseInt(h, 16))).replace(/&amp;/g, '&');

const all = (xml, tag) => [...xml.matchAll(new RegExp(`<${tag}[^>]*>([\\s\\S]*?)</${tag}>`, 'g'))].map((m) => decode(m[1]));
const one = (xml, tag) => all(xml, tag)[0] || '';

const set = process.argv[2] || 'landkarten';
const maxPages = Number(process.argv[3] || 30);
let token = null;
let page = 0;
const records = [];
while (page < maxPages) {
  const url = token
    ? `https://www.e-rara.ch/oai?verb=ListRecords&resumptionToken=${encodeURIComponent(token)}`
    : `https://www.e-rara.ch/oai?verb=ListRecords&metadataPrefix=oai_dc&set=${encodeURIComponent(set)}`;
  const xml = await get(url);
  page++;
  records.push(...all(xml, 'record'));
  const m = xml.match(/<resumptionToken[^>]*>([^<]+)<\/resumptionToken>/);
  const complete = /completeListSize="(\d+)"/.exec(xml);
  if (page === 1) console.log(`set ${set}: completeListSize=${complete ? complete[1] : '?'}`);
  token = m ? m[1] : null;
  if (!token) break;
  await new Promise((r) => setTimeout(r, 120));
}
console.log(`pages read: ${page}, OAI records: ${records.length}`);

const maps = records.map((r) => {
  const types = all(r, 'dc:type');
  const dates = all(r, 'dc:date');
  const title = one(r, 'dc:title');
  const year = (String(dates[0] || '').match(/(1[4-9]\d{2}|20\d{2})/) || [])[0];
  return { title, year: year ? Number(year) : null, isMap: types.includes('Map'), types: types.join(',') };
});
const mapRecs = maps.filter((m) => m.isMap && m.year);
const notSeries = mapRecs.filter((m) => !/^(Atlas|Kartenwerk|Topographischer Atlas|Karte der Schweiz in )/i.test(m.title));
console.log(`maps with a year: ${mapRecs.length}, not a series volume: ${notSeries.length}`);
const byDecade = {};
for (const m of notSeries) { const d = Math.floor(m.year / 10) * 10; byDecade[d] = (byDecade[d] || 0) + 1; }
console.log('by publication decade:', JSON.stringify(byDecade));
const byCentury = {};
for (const m of notSeries) { const c = Math.floor(m.year / 100) * 100; byCentury[c] = (byCentury[c] || 0) + 1; }
console.log('by century:', JSON.stringify(byCentury));
console.log('latest 12 titles:');
for (const m of notSeries.slice(-12)) console.log('  ', m.year, m.title.slice(0, 90));
const uniqTitles = new Set(notSeries.map((m) => m.title.slice(0, 60)));
console.log('distinct title prefixes (60 chars):', uniqTitles.size);

