  /**
   * Dedupe by leading title (the same work often appears in several editions).
   */
  function keepUnique(list, limit) {
    const seen = new Set();
    const out = [];
    for (const r of list) {
      const key = r.title.slice(0, 60);
      if (seen.has(key)) continue;
      seen.add(key);
      out.push(r);
      if (out.length >= limit) break;
    }
    return out;
  }

