cd /home/runner/work/maps-n-stuff/maps-n-stuff && cat > /tmp/probe-narrow.mjs <<'EOF'
// Diagnostic: measure the document width and the histogram box at 320/390/1440 px.
import { spawn } from 'node:child_process';
const CHROME = 'chromium';
const port = 9444;
const proc = spawn(CHROME, ['--headless=new', `--remote-debugging-port=${port}`, '--no-sandbox', '--disable-gpu', '--user-data-dir=/tmp/probe-narrow-profile'], { stdio: 'ignore' });
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
await sleep(2500);
const targets = await (await fetch(`http://127.0.0.1:${port}/json/list`)).json();
const page = targets.find((t) => t.type === 'page');
const ws = new WebSocket(page.webSocketDebuggerUrl);
let id = 0; const pending = new Map();
ws.addEventListener('message', (e) => { const m = JSON.parse(e.data); if (pending.has(m.id)) pending.get(m.id)(m); });
await new Promise((r) => ws.addEventListener('open', r));
const send = (method, params = {}) => new Promise((res) => { const i = ++id; pending.set(i, res); ws.send(JSON.stringify({ id: i, method, params })); });
await send('Page.enable');
for (const width of [320, 390, 1440]) {
  await send('Emulation.setDeviceMetricsOverride', { width, height: 900, deviceScaleFactor: 1, mobile: width < 600 });
  await send('Page.navigate', { url: 'http://127.0.0.1:8787/?from=1547&to=1900' });
  await sleep(2600);
  const m = await send('Runtime.evaluate', { returnByValue: true, expression: `(() => {
    const h = document.getElementById('year-histogram');
    const bins = h ? h.querySelectorAll('button').length : 0;
    const rect = h ? h.getBoundingClientRect() : null;
    return { width: window.innerWidth, doc: document.documentElement.scrollWidth, overflow: document.documentElement.scrollWidth - document.documentElement.clientWidth,
      bins, histW: rect ? Math.round(rect.width) : null, histScroll: h ? h.scrollWidth : null,
      binW: bins ? Math.round((h.querySelector('button').getBoundingClientRect().width) * 10) / 10 : null };
  })()` });
  console.log(width, JSON.stringify(m.result.result.value));
}
ws.close(); proc.kill('SIGKILL');
EOF
node /tmp/probe-narrow.mjs

